import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    if n == 0:
        print("0.0")
        return

    suffixes = []
    for k in range(n):
        t = s[k:] + s[:k]
        suffixes.append(t)

    char_groups = {}
    for k, t in enumerate(suffixes):
        first_char = t[0]
        if first_char not in char_groups:
            char_groups[first_char] = []
        char_groups[first_char].append(k)

    total_winning_cases = 0

    for first_char, indices in char_groups.items():
        if len(indices) == 1:
            total_winning_cases += 1
            continue

        candidates = indices
        found_optimal = False

        for pos in range(1, n):
            groups_at_pos = {}
            for idx in candidates:
                t = suffixes[idx]
                char_at_pos = t[pos]
                if char_at_pos not in groups_at_pos:
                    groups_at_pos[char_at_pos] = []
                groups_at_pos[char_at_pos].append(idx)

            best_win_count = 0
            for group in groups_at_pos.values():
                if len(group) == 1:
                    best_win_count += 1

            if best_win_count > 0:
                total_winning_cases += best_win_count
                found_optimal = True
                break

        if not found_optimal:
            pass

    probability = total_winning_cases / n
    print(f"{probability:.15f}")

if __name__ == "__main__":
    solve()
